figures.script:
diagram("mode: sequence
[main] as m
[Base] as b
[Derived] as d
m -> d : create Derived
d -> b : Base() runs first
b --> d : base part ready
d -> d : Derived() body
m -> d : object destroyed
d -> d : ~Derived() first
d -> b : ~Base() last
@0 m -> d : create Derived
@1 d -> b : Base() runs first
@2 b -> d : base part ready
@3 d -> d : Derived() body
@4 m -> d : object destroyed
@5 d -> d : ~Derived() first
@6 d -> b : ~Base() last");

diagram("mode: sequence
[Animal* p] as p
[vptr → Dog vtable] as v
[Dog::speak] as d
[Animal::speak] as a
p -> v : p->speak()
v -> d : look up slot 0
d --> p : "Woof"
@0 p -> v : p->speak()
@1 v -> d : look up slot 0
@2 d -> p : "Woof"");
